+// Sum the integer line cents first, then apply the percentage discount to the
+// subtotal and round exactly once. Rounding inside the accumulator rounds each
+// line independently, which inflates the total whenever a discounted line
+// rounds up on its own (e.g. two 1c lines at 50% off => 1 + 1 = 2 instead of 1).
+export function totalCents(lines, discountPercent) {
+  const subtotalCents = lines.reduce((sum, line) => sum + line.cents * line.quantity, 0);
+  return Math.round(subtotalCents * (1 - discountPercent / 100));
+}

